			q = { "How do I get Bankai Guild chat in its own tab?", "My Bankai Guild tab stopped getting the channels" },
			text = "Type /bk chatwindow tab, then right-click General, Create New Window, name it Bankai Guild: the channels move there. On the beta, redo it after a relog.",
			long = "Click Add an Bankai Guild tab on the Chat tab (or type /bk chatwindow tab), then right-click General, Create New Window, and name it Bankai Guild: the channels move there. Untick other chats in that tab's settings. The beta forgets that choice at login, so redo it after a relog." },
		{ id = "feat-chattynator", topic = "features",
			q = { "I use Chattynator, how do I get the Bankai Guild chats in a tab?", "My Chattynator tab doesn't show the Bankai Guild chats", "Does Bankai Guild work with Chattynator?" },
			text = "With Chattynator: type /bk chatwindow tab, make a tab named Bankai Guild (the + after its tabs), then tick Bankai Guild under Addons in its Tab Settings.",
			long = "Type /bk chatwindow tab: it says how to make a Chattynator tab named Bankai Guild (the + after its tabs, then Rename tab), and the channels go there once it exists. Tick Bankai Guild under Addons in that tab's Tab Settings, or it stays empty. /bk chatwindow <name> picks another tab." },
		{ id = "feat-channels", topic = "features",
			q = { "How do I talk in Bankai Guild chat?", "Who can read [Council]?", "Is Bankai Guild chat private?" },
			text = "Talk with /bg, /bgc and /bgl. /bk chat on turns chats on. Not private: never share passwords there.",
			long = "/bg for [Bankai Guild] (everyone), /bgc for [Council] (Council and up), /bgl for [Elders]. The chats stay off until you say yes (/bk chat on). They aren't private: anyone on the channel can read all three, so never share passwords." },
		{ id = "feat-chat-off", topic = "features",
			q = { "How do I turn off the /bg spam?", "Can I hide Bankai Guild chat?" },
			text = "Type /bk chat off to turn chats off. /bk mute bankaiguild hides one channel. /bk filter add <word> hides lines with a word.",
			long = "/bk chat off turns the chats off on your client: nothing shows or sends. Or /bk mute bankaiguild to hide just that channel, or /bk filter add <word> to hide lines with a word." },
		{ id = "feat-block-terms", topic = "features",
			q = { "How do I hide certain words?", "What does /bk filter do?" },
			text = "Type /bk filter add <word> to hide lines with it, on your screen only. /bk filter shared off ignores the moderators' list.",
			long = "/bk filter add <word> hides addon lines with that word on your screen only: chats, writs, decrees and Poll. The sender isn't blocked. Moderators also keep a shared list; /bk filter shared off ignores it." },
		{ id = "feat-watch", topic = "features",
			q = { "What's The Watch?", "Who can see The Watch?", "Does its ban list reject players automatically?" },
			text = "The Watch is a private guild moderation desk: deliberate warnings, timeouts, Watch or Ban marks, private recovery and an audit trail. It never kicks, demotes, ignores or auto-rejects anyone.",
			long = "The Watch is private to a guild's Elder, Council and live signed moderators. Warnings escalate, reset with Clear and decay after 30 days. Actions and bounded recovery use logged officer whispers, never broadcasts. Nothing kicks, demotes, ignores or auto-rejects; every manual change is audited." },
		{ id = "feat-judgments", topic = "features",
			q = { "How does a case reach the Shogun?", "How does the High Council vote on a case?" },
			text = "A case's page sends it to the Shogun. The High Council votes for 24 hours, then the Shogun's word is final. No sanction comes of it by itself.",
			long = "An officer sends a case from its page to the Shogun: the card's facts and his finding, never who reported it. The High Council votes for 24 hours (the majority of those who answered), then the Shogun's word is final. Nothing happens by itself: the officers decide what to do." },
		{ id = "feat-church", topic = "features",
			q = { "What's the Missionary Church of Bankai Guild?", "How do I name a missionary?", "Who are the Apostles?" },
			text = "The Church: a Head, the Twelve Apostles and their missionaries, who name more missionaries; one correspondent per guild. Name one on the Church tab or right-click a player.",
			long = "The Church brings new players in: the Twelve Apostles from the author's signed list (the one it marks is the Head), missionaries each Apostle names (and each missionary may name more), and one correspondent per guild. Name a missionary on the Church tab or with a right-click." },
		{ id = "feat-church-count", topic = "features",
			q = { "How does the Church count my recruits?", "Why is my recruit still pending?", "How are Church points made?" },
			text = "From your guild's log: pending until another player's addon confirms. New to Bankai Guild only. 10 points, +5 after 7 days, plus 25/10/5% of three levels under you.",
			long = "Your guild's log shows the invite and the join; another player's addon confirms it (only yours: pending). Only players new to Bankai Guild count. 10 points each, 5 more if he stays 7 days, plus 25%, 10% and 5% of the points of three levels under you. Your own work counts most." },
		{ id = "feat-bones-place", topic = "features",
			q = { "Where can I play Bones?", "Why won't my Bones table start?", "Can I play Bones at a camp?" },
			text = "Bones can be played at a tavern or at a camp: in one party, within 10 yards, at the same inn or by a camp one of you dropped here (/bk camp). Practice works anywhere.",
			long = "Bones can be played at a tavern or at a camp: both of you in one party, within about 10 yards, at the same inn or by a camp one of you dropped in that zone (/bk camp, with /bk location on). Walk off and the game pauses; gone a minute, you forfeit. Practice works anywhere." },
		{ id = "feat-no-arbiters", topic = "features",
			q = { "Do I need an arbiter for a duel or Bones?", "Where did the arbiters go?" },
			text = "No arbiter needed: with no bets in 1.1.6, a duel or a Bones game is between the two players, for points.",
			long = "No. Arbiters are there for the money, and 1.1.6 has no bets: a duel or a Bones game is between the two players, for points. Nothing asks for an arbiter or waits on one, and there is no Arbiter page while there are no bets." },
		{ id = "feat-duel-points", topic = "features",
			q = { "How are duel points worked out?", "Does my level matter in the duel ranking?" },
			text = "Duel points are Elo with levels in it: beat a higher level for more; a much lower one pays little or nothing, and losing to a much higher one costs little.",
			long = "Duel points are Elo with your levels in it: each level between you counts as 50 rating points. Beating someone 10 levels up pays about double an even win; beating someone 10 levels down pays 1 point, and 16 levels down nothing. Losing to a much higher level costs little." },
		{ id = "feat-find-player", topic = "features",
			q = { "How do I find someone to duel or play Bones?", "Can I search only near my level?" },
			text = "Find in the Arena (duels) or the Bones window: pick the level (any, within 5 or 10) and the reach (your zone or continent). Let others find me makes you findable.",
			long = "Open Find in the Arena for a duel, or in the Bones window for Bones. Pick the level (any, within 5 or within 10 of yours) and the reach (your zone or your continent); the nearest players come first. Tick Let others find me to be found yourself." },
		{ id = "feat-decrees", topic = "features",
			q = { "What's a Call to arms?", "How do I send a muster?" },
			text = "The Crown calls the army: Call to arms (/bk arms) or Muster (/bk muster); another guild's officers call their own guild alone. Add test for a preview only you see.",
			long = "The Crown (the Shogun, his Steward, <Elfcore>'s officers; other guilds hear those named Hands) sends the army a Call to arms (alarm, map marker) or a Muster (30-minute rally point); another guild's officers call their own guild alone. Royal decrees: the Crown and the High Council. Others get a preview: /bk arms test." },
		{ id = "feat-alert-sounds", topic = "features",
			q = { "How do I turn off the alert sounds?", "Why didn't I get the raid warning in my dungeon?" },
			text = "Type /bk sound off for all, or /bk sound <kind> off. In instances alerts wait; /bk alerts always shows them at once.",
			long = "/bk sound off silences them all, or /bk sound poll off (or another kind) for one. In an instance or while Busy, alerts wait until you're out; /bk alerts always shows them at once." },
		{ id = "feat-writs", topic = "features",
			q = { "What's a Royal Writ?", "How do I answer a writ?" },
			text = "A letter from the Shogun in the Decrees tab. Elders and Council can answer As you command.",
			long = "A letter from the Shogun in the Decrees tab, to the Elders, to Elders and Council, or to the whole army. Elders and Council can answer As you command, and the Shogun sees how many did." },
		{ id = "feat-net-off", topic = "features",
			q = { "Someone's lines disappeared", "What's net-off?", "Can moderators hide spammers?" },
			text = "Moderators can hide a character or guild from the network. Decrees stays member-visible and shows your own reason; authorized officers also see net-off in The Watch.",
			long = "Moderators can hide a character or take a guild off the network for everyone. Decrees lists who, why, by whom and when for every member, with a red reason line when it is you or your guild; authorized officers also see the section in The Watch." },
		{ id = "feat-acts-log", topic = "features",
			q = { "Who opened the gates?", "What's /bk log?" },
			text = "Type /bk log: decrees, gates and pardons your client saw, with who did them. Kept on your PC only.",
			long = "What this client saw: decrees, gates, pardons and the Shogun's switches, each with who did it. It's on the Decrees tab or /bk log, kept on your computer only and never sent." },
		{ id = "feat-throne", topic = "features",
			q = { "What can the Shogun do in the addon?", "What's the Throne tab?" },
			text = "The Shogun's tab has his Agenda, week, key rotation and Hold Court. Its private queue is in The Watch; Summon the Elders and gates are on Realm.",
			long = "The Shogun's own tab holds his Agenda, week, key rotation and Hold Court button. His other tools sit where they belong: the private court queue in The Watch, Summon the Elders and the gates on Realm, and writs in Decrees." },
		{ id = "feat-agenda", topic = "features",
			q = { "I got a popup about a royal event", "What's the Shogun's Agenda?" },
			text = "The Shogun's Agenda: a popup with the next royal event, shown on the Census, with reminders 10 and 1 min before.",
			long = "The Shogun sets the next royal event: everyone gets a popup with what, when and where, sees it on the Census, and gets reminders 10 minutes and 1 minute before." },
		{ id = "feat-summon-elders", topic = "features",
			q = { "I got 'The Shogun summons his Elders'", "What's Summon the Elders?" },
			text = "A roll call for Elders and Council: answer Present or Busy. The Shogun sees who answered.",
			long = "A roll call for Elders and Council online: answer Present or Busy. The Shogun sees who answered and who didn't, and the Realm tab marks each of them for a while." },
		{ id = "feat-hold-court", topic = "features",
			q = { "What's Hold Court?", "How do I ask the Shogun for an audience?" },
			text = "The Shogun opens court from the Throne and calls its queue from The Watch. Players in his zone get a line; one click asks for an audience.",
			long = "When the Shogun opens court from the Throne, everyone in his zone gets a line on the Census and Realm tabs. One click asks for an audience, and he calls players from the private queue in The Watch." },
		{ id = "feat-steward-hands", topic = "features",
			q = { "What's the Shogun's Steward?", "Who are the Hands of the Shogun?" },
			text = "The Steward acts for the Shogun. Hands are players named to run his Agenda, Poll, roll call and gates.",
			long = "The Steward acts for the Shogun: he names Hands, manages the treasury's keepers and uses most of the Shogun's tools (not court, writs, pardons or his crown). Hands are players the Shogun or Steward names to run the roll call, Agenda, Poll, inspection and gates in his name." },
		{ id = "feat-poll", topic = "features",
			q = { "What's Poll?", "How do I vote?" },
			text = "Polls from the Shogun, his Steward or a Hand, or from your guild master: tick your answer before the timer ends. /bk poll off keeps them in chat.",
			long = "Polls from the Shogun, his Steward or a Hand (to the army, the High Council or the guild masters), or from a guild master to his guild. A window shows 2 to 6 answers and a countdown; your vote goes to whoever asked, and those asked see the result. /bk poll off keeps them in chat." },
		{ id = "feat-treasury", topic = "features",
			q = { "What's the Treasury tab?", "How is the treasury balance counted?" },
			text = "The treasury from its keepers' books: gifts by trade or mail count. Everyone sees what the Shogun chooses to show.",
			long = "The army's treasury, from its keepers' books: gold and items given to a keeper by trade or mail are donations. Keepers, the Shogun and his Steward see it all; everyone else sees what the Shogun chooses to show." },
		{ id = "feat-guild-bank", topic = "features",
			q = { "Can I see the Bankai Guild guild bank?", "What's in <Elfcore>'s bank?" },
			text = "When the Shogun shows it, the Treasury tab has a snapshot of <Elfcore>'s bank, with search.",
			long = "When the Shogun shows the treasury's book, the Treasury tab has a snapshot of <Elfcore>'s guild bank, with search and what's gone since the last snapshot. It's a picture: nothing gets moved." },
		{ id = "feat-treasury-requests", topic = "features",
			q = { "How do I ask the treasury for items?", "What's /bk need?" },
			text = "Elders and Council: /bk need 10 then shift-click the item. Keepers see it and you're told when it's done.",
			long = "Elders and Council: /bk need 10 and shift-click the item. The keepers see it on their Treasury tab and mark it done or declined, and you're told. The handover is still a normal trade or mail." },
		{ id = "feat-sister-banks", topic = "features",
			q = { "Can the Shogun see our guild bank?", "What's /bk bank share?" },
			text = "Only with a yes: /bk bank share on shows your bank snapshot in the Guild treasuries, by whisper. Off takes it back.",
			long = "Only if your guild master or an officer says yes. /bk bank share on shows your bank's snapshot in the Guild treasuries, to the Shogun, the High Council (his Stewards and Hands among them), the Treasurer and the author, by whisper, never on the channel. Off takes it back." },
		{ id = "feat-donations", topic = "features",
			q = { "How do I know where to donate?", "What's 'taking donations'?" },
			text = "When a keeper takes donations, a line on the Realm and Treasury tabs says who and where.",
			long = "When a keeper types /bk donations on, everyone sees a line on the Realm and Treasury tabs saying he's taking donations, with his zone if he shares it. It goes off when he logs out." },
		{ id = "feat-dues", topic = "features",
			q = { "What are the dues?", "How do I pay the dues?" },
			text = "Open mail or a trade with the Treasurer, then click Send this week's dues on the Treasury tab. Nothing is locked behind paying.",
			long = "One fixed weekly amount for everyone, set by the Shogun, sent to the Treasurer. Open your mailbox (Send Mail) or a trade with him, then click Send this week's dues on the Treasury tab: it fills everything in for you to confirm. Nothing is locked behind paying." },
		{ id = "feat-backup", topic = "features",
			q = { "My settings reset, can I save them?", "What's /bk backup?" },
			text = "Type /bk backup to copy your settings as text. Keep it; /bk restore brings it back after a wipe.",
			long = "/bk backup copies your settings (and a keeper's treasury book) as text: keep it in a file. When the beta wipes addon data, /bk restore pastes it back. Nothing is uploaded, and it never holds the channel key." },
		{ id = "feat-world-map", topic = "features",
			q = { "How do I see the army on the map?", "How do I turn off the map circles?" },
			text = "The map shows soldiers per zone. The round Bankai Guild button (bottom left of the map) or /bk map turns it on or off.",
			long = "The world map shows soldiers per zone and continent, decree icons, the Shogun's crown and camps. The round Bankai Guild button at the bottom left of the map turns them on or off; /bk map too. In gamepad mode only continent totals show." },
		{ id = "feat-guildmate-dots", topic = "features",
			q = { "How do I see guildmates on the map?", "How do I share my position with my guild?" },
			text = "Type /bk share to share your spot with your guild; /bk mates shows guildmates on your map.",
			long = "Off by default. /bk share shares your position with your guild, and /bk mates shows guildmates' dots on your map and minimap. It stays inside your guild." },
		{ id = "feat-borders-nameplates", topic = "features",
			q = { "What are the gold wings on portraits?", "What's the star on nameplates?", "How do I turn them off?" },
			text = "Borders and marks: the Shogun gold, the High Council silver, guild masters and those they name bronze, other members a star (not in guild chat). /bk borders, nameplates or chatmarks off hides them.",
			long = "Elite borders on your target, focus and portrait: gold wings for the Shogun, silver for the High Council, bronze for guild masters, plain bronze for those they name. Nameplates and the game's chat show the same marks, a star for other members. /bk borders, nameplates or chatmarks off hides them." },
		{ id = "feat-alt-links", topic = "features",
			q = { "How do I link my alts?", "Why does my alt count twice?" },
			text = "Type /bk alt add Name on your main, then say yes on the alt. On the beta the offer can't reach the alt yet.",
			long = "/bk alt add Name on your main, then log that alt and say yes, and the census and treasury count you once. Heads up: the beta forgets addon data at login, so right now the offer can't reach the alt." },
		{ id = "feat-help-status", topic = "features",
			q = { "What are the commands?", "How do I use this addon?", "Where's the help?" },
			text = "Help button left of the X, or /bk help for all commands. /bk status shows diagnostics.",
			long = "Click the help button left of the window's X: what each tab is for, privacy switches, links and Report a bug. /bk help lists every command, and /bk status shows what your addon knows." },
		{ id = "feat-search", topic = "features",
			q = { "Can I search the lists?", "How do I find a name on a tab?" },
			text = "Most tabs have a search box on top. It only filters what you see.",
			long = "The Census, Realm, Treasury, Decrees and Chat tabs have a search box: guilds, Elders, players or zones on the Census, members on the Realm, donors and bank items on the Treasury, the log on Decrees, lines on Chat. It only filters." },
		{ id = "feat-open-window", topic = "features",
			q = { "How do I open Bankai Guild?", "Where's the window?" },
			text = "Type /bk, or click the minimap button or the round button in your guild window.",
			long = "Type /bk, click the minimap button, or the round button in your guild window. Shift-click the minimap button for the Chat tab; right-click it to show or hide the map markers." },
		{ id = "feat-gamepad", topic = "features",
			q = { "Does it work with a controller?", "The game froze in gamepad mode" },
			text = "With the gamepad UI Bankai Guild uses its own windows. If the game blocks something, /reload, then report it from the help button.",
			long = "Yes. With Blizzard's gamepad UI, Bankai Guild asks in its own windows (answer with the cursor) and leaves the world map alone. If the game blocks something, /reload clears it; report it from the help button, not /bk bug." },
		{ id = "feat-languages", topic = "features",
			q = { "Is it in Portuguese or Spanish?", "How do I change the language?" },
			text = "It follows your game language: English and Portuguese in full, Spanish, French and German for the main screens. Page help is in English.",
			long = "It follows your game language. English and Portuguese are complete; Spanish, French and German cover the main screens. The pages' ? help and the Answers are in English for now. Only what's on your screen changes." },
		{ id = "feat-key-block", topic = "features",
			q = { "How do I seal the channel?", "How do I ignore someone in Bankai Guild?" },
			text = "Officers: /bk key <secret> (same as other guilds) seals the channel. /bk block <name> ignores a player.",
			long = "Officers: /bk key <secret> seals the Bankai Guild channel so outsiders can't join. Use the same secret as the other Bankai Guild guilds or your guild splits off. /bk block <name> ignores everything a player sends." },
		{ id = "feat-bankaiguild-link", topic = "features",
			q = { "How do I get my Discord role?", "What's /bk discord?" },
			text = "Bankai Guild Link (Discord roles) isn't open yet: it comes with a later update of the addon.",
			long = "Bankai Guild Link will prove your character to the Bankai Guild bot on Discord for your role, but it isn't open yet: it needs a later addon update. Until then /bk discord just says it's not open." },
		{ id = "feat-issue-reporter", topic = "features",
			q = { "How do I hide Blizzard's Issue Reporter box?", "What's that Issue Reporter window at login?" },
			text = "Click Hide on the box or /bk issuereporter hide. The beta forgets it at login, so redo it after a relog.",
			long = "Click Hide on the box, or type /bk issuereporter hide; /bk issuereporter show brings it back. The beta forgets addon settings at login, so you may have to hide it again after a relog. With the gamepad UI Bankai Guild leaves it alone." },
		{ id = "feat-bridge", topic = "features",
			q = { "What's BankaiGuildBridge?", "Can other addons read Bankai Guild?" },
			text = "A read-only door for the moderators' companion addon. It sends and changes nothing.",
			long = "A read-only door for the moderators' companion addon: it can ask whether a name is a High Councillor and read chat lines your addon already accepted. It sends and changes nothing in Bankai Guild." },
		{ id = "feat-workshop", topic = "features",
			q = { "What's the Workshop tab?", "Why did I get a roll call?" },
			text = "The author's tab for versions and bug reports. You answer roll calls only if you said yes; /bk rollcall off stops them.",
			long = "The author's own tab: roll calls for versions and errors, asking out-of-date players to update, and bug reports players send him. Only he has it. You answer roll calls only if you said yes; /bk rollcall off stops them." },
		{ id = "feat-page-help", topic = "features",
			q = { "What does the ? on a page do?", "Where's the explanation of this page?" },
			text = "The ? in each page's bottom box explains that page and why its counts can differ. The Chat tab has none: the help button left of the X covers it.",
			long = "Each page has a ? in its bottom box: it explains that page and, where it shows counts, why they can differ between players. The Chat tab has no bottom box, so no ? of its own. The help button left of the X is the general help." },
		{ id = "feat-quick-answers", topic = "features",
			q = { "What's the Answers button?", "How do moderators answer questions so fast?" },
			text = "The author, High Council and Stewards have an Answers button: a click puts a ready answer in the box to edit, nothing is sent by itself.",
			long = "The author, the High Council and the Stewards get an Answers button at the end of the Chat tab's box and in Bankai Guild's whisper window: short ready answers by topic, searchable. A click puts one in the box to edit; nothing is sent until you do." },
		{ id = "help-install", topic = "install-update-bugs",
			q = { "How do I install Bankai Guild?", "Where do I get the addon?" },
			text = "Get Bankai Guild Guild in the CurseForge app or WowUp (pick the Forever install), then restart the game.",
			long = "Get Bankai Guild Guild in the CurseForge app or WowUp and pick your Forever (beta) game install, not Classic Era. Then restart the game. By hand: unzip it so you end up with Interface > AddOns > Bankai Guild > BankaiGuild.toc." },
		{ id = "help-update", topic = "install-update-bugs",
			q = { "How do I update?", "I updated but nothing changed" },
			text = "Update in the CurseForge app or WowUp, then close and reopen the game (a /reload isn't enough).",
			long = "Update Bankai Guild Guild in the CurseForge app or WowUp, then close and reopen the game: a /reload won't load a new version properly. /bk status shows your version on its first line." },
		{ id = "help-check-version", topic = "install-update-bugs",
			q = { "Which version do I have?", "Am I up to date?" },
			text = "Type /bk status: the first line is your version, and a later line says if a newer one is out.",
			long = "Type /bk status: the first line shows your version, and a later line shows the latest release your addon heard of and whether you're behind." },
		{ id = "help-old-version", topic = "install-update-bugs",
			q = { "Do I have to update?", "My version is old, does it matter?" },
			text = "Please update: old versions drop what new ones send, and your guild can look broken to others. CurseForge or WowUp, then restart.",
			long = "Please do. Older versions drop what newer ones send, so your census can look off and your guild can look broken to everyone else. Update in the CurseForge app or WowUp, then restart the game." },
		{ id = "help-out-of-date", topic = "install-update-bugs",
			q = { "The AddOns list says 'out of date'", "Bankai Guild is disabled as out of date" },
			text = "That's the game's patch check, not Bankai Guild. Tick Load out of date AddOns in the AddOns list.",
			long = "That's the game comparing against its own patch number, not Bankai Guild's version. Tick Load out of date AddOns in the AddOns list and it loads." },
		{ id = "help-author-update-popup", topic = "install-update-bugs",
			q = { "I got a window saying the author asks me to update", "Is the update popup legit?" },
			text = "If it says the author asks, it's real: only his character can send it, and only if you're behind. Update and restart. /bk rollcall off stops his.",
			long = "If it says the author of the addon asks you, it's real: only his character can send it, and only when your version is older than the one he released. Update in the CurseForge app or WowUp, then restart. /bk rollcall off stops his. One naming a player is that player's ask." },
		{ id = "help-report-bug", topic = "install-update-bugs",
			q = { "Where do I report a bug?", "How do I send the author an error?" },
			text = "Bankai Guild window, help button (left of the X), Report a bug. If the author's online there's a button to send it to him.",
			long = "Open the Bankai Guild window, click the help button left of the X, then Report a bug. Copy the text to GitHub or a CurseForge comment. If the author is online, that window also has a button that sends it straight to him in game." },
		{ id = "help-blocked", topic = "install-update-bugs",
			q = { "The game says it blocked Bankai Guild", "I got an 'action blocked' error" },
			text = "A /reload clears it. Then report it: Bankai Guild window, help button, Report a bug (not /bk bug with the gamepad).",
			long = "A /reload clears it. Then tell us what happened: Bankai Guild window, help button, Report a bug. With the gamepad UI, don't type /bk bug in chat; use the button, since a typed command can set the block off again." },
		{ id = "help-settings-reset", topic = "install-update-bugs",
